    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endAGV(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // ID
        $builder->required($o, 6);  // EPOCH
        $builder->required($o, 18);  // UNITS
        $builder->required($o, 38);  // PROJECTION_PARAMETERS
        $builder->required($o, 44);  // LEVELS
        $builder->required($o, 64);  // PAYLOAD_SHA256
        $builder->required($o, 68);  // PROVENANCE
        return $o;
    }

    public static function finishAGVBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$AGV");
    }
